class CustomEngineInterface {
public:
    using result_type = uint32_t;
    static constexpr result_type min() { return 0; }
    static constexpr result_type max() { return 0xFFFFFFFFU; }

    CustomEngineInterface() = default;
    template<typename SeedSeq>
    explicit CustomEngineInterface(SeedSeq& seq) { /* use seq to init state */ }

    void seed(result_type s) { state_ = s; }
    void discard(unsigned long long z) { /* fast forward state */ }

    result_type operator()() {
        state_ = state_ * 1664525 + 1013904223; // Simple LCG logic
        return state_;
    }

    friend bool operator==(const CustomEngineInterface& a, 
                           const CustomEngineInterface& b) {
        return a.state_ == b.state_;
    }

private:
    result_type state_ = 1;
};
